  function applyLanguage(language) {
    var selected = translations[language] || {};
    document.documentElement.lang = language === "pt" ? "pt-BR" : language;
    document.title = language === "en" ? "Private Travel Proposal | Jeri Rota" : language === "fr" ? "Proposition de Voyage Privé | Jeri Rota" : "Proposta de Viagem Privativa | Jeri Rota";
    textNodes.forEach(function (item) {
      var value = language === "pt" ? item.source : (selected[item.source] || item.source);
      item.node.nodeValue = value;
    });
    originalAlts.forEach(function (item) {
      item.image.alt = language === "pt" ? item.source : ((altTranslations[language] && altTranslations[language][item.source]) || item.source);
    });
    document.querySelectorAll("[data-language]").forEach(function (button) {
      button.setAttribute("aria-pressed", button.getAttribute("data-language") === language ? "true" : "false");
    });
    var languageNav = document.querySelector(".language-switcher");
    if (languageNav) languageNav.setAttribute("aria-label", language === "en" ? "Select language" : language === "fr" ? "Choisir la langue" : "Selecionar idioma");
    var localizedApprovalMessage = language === "en"
      ? "Hello, Christhofer. I have reviewed the proposal for our trip from October 28 to November 6, 2026, and I would like to confirm the reservation."
      : language === "fr"
        ? "Bonjour Christhofer. J’ai étudié la proposition pour notre voyage du 28 octobre au 6 novembre 2026 et je souhaite confirmer la réservation."
        : approvalMessage;
    var localizedContactMessage = language === "en"
      ? "Hello, Christhofer. I would like to discuss the travel proposal for Edmond Michel & Caroline."
      : language === "fr"
        ? "Bonjour Christhofer. Je souhaite échanger au sujet de la proposition de voyage d’Edmond Michel & Caroline."
        : contactMessage;
    if (approve) approve.href = whatsappUrl(localizedApprovalMessage);
    if (contact) contact.href = whatsappUrl(localizedContactMessage);
    var url = new URL(window.location.href);
    if (language === "pt") url.searchParams.delete("lang"); else url.searchParams.set("lang", language);
    window.history.replaceState({}, "", url);
    try { window.localStorage.setItem("jeri-rota-proposal-language", language); } catch (error) {}
  }

  document.querySelectorAll("[data-language]").forEach(function (button) {
    button.addEventListener("click", function () { applyLanguage(button.getAttribute("data-language")); });
  });
  var requestedLanguage = new URL(window.location.href).searchParams.get("lang");
  if (!/^(pt|en|fr)$/.test(requestedLanguage || "")) {
    try { requestedLanguage = window.localStorage.getItem("jeri-rota-proposal-language"); } catch (error) {}
  }
  applyLanguage(/^(pt|en|fr)$/.test(requestedLanguage || "") ? requestedLanguage : "pt");
